121	/**
122	 * RouterClientRMService is a service that runs on each router that can be used
123	 * to intercept and inspect {@link ApplicationClientProtocol} messages from
124	 * client to the cluster resource manager. It listens
125	 * {@link ApplicationClientProtocol} messages from the client and creates a
126	 * request intercepting pipeline instance for each client. The pipeline is a
127	 * chain of {@link ClientRequestInterceptor} instances that can inspect and
128	 * modify the request/response as needed. The main difference with
129	 * AMRMProxyService is the protocol they implement.
130	 */
131	public class RouterClientRMService extends AbstractService
132	    implements ApplicationClientProtocol {
133	
134	  private static final Logger LOG =
135	      LoggerFactory.getLogger(RouterClientRMService.class);
136	
137	  private Server server;
138	  private InetSocketAddress listenerEndpoint;
139	
140	  // For each user we store an interceptors' pipeline.
141	  // For performance issue we use LRU cache to keep in memory the newest ones
142	  // and remove the oldest used ones.
143	  private Map<String, RequestInterceptorChainWrapper> userPipelineMap;
144	
145	  public RouterClientRMService() {
146	    super(RouterClientRMService.class.getName());
147	  }
148	
149	  @Override
150	  protected void serviceStart() throws Exception {
151	    LOG.info("Starting Router ClientRMService");
152	    Configuration conf = getConfig();
153	    YarnRPC rpc = YarnRPC.create(conf);
154	    UserGroupInformation.setConfiguration(conf);
155	
156	    this.listenerEndpoint =
157	        conf.getSocketAddr(YarnConfiguration.ROUTER_BIND_HOST,
158	            YarnConfiguration.ROUTER_CLIENTRM_ADDRESS,
159	            YarnConfiguration.DEFAULT_ROUTER_CLIENTRM_ADDRESS,
160	            YarnConfiguration.DEFAULT_ROUTER_CLIENTRM_PORT);
161	
162	    int maxCacheSize =
163	        conf.getInt(YarnConfiguration.ROUTER_PIPELINE_CACHE_MAX_SIZE,
164	            YarnConfiguration.DEFAULT_ROUTER_PIPELINE_CACHE_MAX_SIZE);
165	    this.userPipelineMap = Collections.synchronizedMap(
166	        new LRUCacheHashMap<String, RequestInterceptorChainWrapper>(
167	            maxCacheSize, true));
168	
169	    Configuration serverConf = new Configuration(conf);
170	
171	    int numWorkerThreads =
172	        serverConf.getInt(YarnConfiguration.RM_CLIENT_THREAD_COUNT,
173	            YarnConfiguration.DEFAULT_RM_CLIENT_THREAD_COUNT);
174	
175	    this.server = rpc.getServer(ApplicationClientProtocol.class, this,
176	        listenerEndpoint, serverConf, null, numWorkerThreads);
177	
178	    // Enable service authorization?
179	    if (conf.getBoolean(
180	        CommonConfigurationKeysPublic.HADOOP_SECURITY_AUTHORIZATION, false)) {
181	      refreshServiceAcls(conf, RouterPolicyProvider.getInstance());
182	    }
183	
184	    this.server.start();
185	    LOG.info("Router ClientRMService listening on address: "
186	        + this.server.getListenerAddress());
187	    super.serviceStart();
188	  }
189	
190	  @Override
191	  protected void serviceStop() throws Exception {
192	    LOG.info("Stopping Router ClientRMService");
193	    if (this.server != null) {
194	      this.server.stop();
195	    }
196	    userPipelineMap.clear();
197	    super.serviceStop();
198	  }
