205	  /**
206	   * Returns the comma separated intercepter class names from the configuration.
207	   *
208	   * @param conf
209	   * @return the intercepter class names as an instance of ArrayList
210	   */
211	  private List<String> getInterceptorClassNames(Configuration conf) {
212	    String configuredInterceptorClassNames =
213	        conf.get(YarnConfiguration.ROUTER_CLIENTRM_INTERCEPTOR_CLASS_PIPELINE,
214	            YarnConfiguration.DEFAULT_ROUTER_CLIENTRM_INTERCEPTOR_CLASS);
215	
216	    List<String> interceptorClassNames = new ArrayList<String>();
217	    Collection<String> tempList =
218	        StringUtils.getStringCollection(configuredInterceptorClassNames);
219	    for (String item : tempList) {
220	      interceptorClassNames.add(item.trim());
221	    }
222	
223	    return interceptorClassNames;
224	  }
