  /**
   * Creates an instance of RequestInterceptor. The pipeline is created from
   * the configuration.
   *
   * @param conf configuration
   * @param interceptorClassConfKey configuration key for the interceptor
   *          class names
   * @param defaultInterceptorClassValue default value for the interceptor
   *          class names
   * @param clazz the class of the interceptor
   * @param <R> the type of the interceptor
   * @return the reference of the first interceptor in the chain
   */
  public static <R> R createRequestInterceptorPipeline(Configuration conf,
      String interceptorClassConfKey, String defaultInterceptorClassValue,
      Class<R> clazz) {
    String configuredInterceptorClassNames = conf.get(interceptorClassConfKey,
        defaultInterceptorClassValue);
    List<String> interceptorClassNames = new ArrayList<>();
    Collection<String> tempList =
        StringUtils.getStringCollection(configuredInterceptorClassNames);
    for (String item : tempList) {
      interceptorClassNames.add(item.trim());
    }

    R pipeline = null;
    R current = null;
    for (String interceptorClassName : interceptorClassNames) {
      try {
        Class<?> interceptorClass = conf.getClassByName(interceptorClassName);
        if (clazz.isAssignableFrom(interceptorClass)) {
          R interceptorInstance = (R) ReflectionUtils
              .newInstance(interceptorClass, conf);
          if (pipeline == null) {
            pipeline = interceptorInstance;
            current = interceptorInstance;
            continue;
          } else {
            Method method = clazz.getMethod("setNextInterceptor", clazz);
            method.invoke(current, interceptorInstance);
            current = interceptorInstance;
          }
        } else {
          throw new YarnRuntimeException(
              "Class: " + interceptorClassName + " not instance of "
                  + clazz.getCanonicalName());
        }
      } catch (ClassNotFoundException e) {
        throw new YarnRuntimeException(
            "Could not instantiate " + clazz.getSimpleName() + ": "
                + interceptorClassName, e);
      } catch (Exception e) {
        throw new YarnRuntimeException(e);
      }
    }

    if (pipeline == null) {
      throw new YarnRuntimeException(
          "RequestInterceptor pipeline is not configured in the system");
    }
    return pipeline;
  }
